import numpy as np
rng = np.random.default_rng(0)
def nb_params(X, y):
    # Bernoulli naive Bayes: prior P(y=1) + P(x_j=1 | y=c) for every class c and attribute j
    prior = {'P(y=1)': y.mean()}   # P(y=0) = 1 - P(y=1) is not a new parameter
    cond = {f'P(x{j+1}=1|y={c})': X[y == c, j].mean() for c in (0, 1) for j in range(X.shape[1])}
    return {**prior, **cond}
for K in (3, 4, 5, 10):
    X = rng.integers(0, 2, size=(200, K)); y = rng.integers(0, 2, size=200)
    n = len(nb_params(X, y))
    full_joint = 2 * (2**K - 1) + 1          # no independence assumption
    opts = {'A': 2**K + 1, 'B': 2*K + 1, 'C': 2**(K+1) + 1, 'D': K**2 + 1}
    print(K, 'naive Bayes params =', n, '| full joint =', full_joint, '| matching options:', [k for k, v in opts.items() if v == n])
